```java
public Flowable<List<String>> fetchFromNetFlowable() {
    offset = 0;
    return Flowable.generate(new Consumer<Emitter<List<String>>>() {
        @Override
        public void accept(Emitter<List<String>> emitter) throws Exception {
            List<String> subset = networkCall(offset);
            boolean loadNext = subset.size() > 0;
            offset += subset.size();

            final ArrayList<String> validItems = new ArrayList<>();
            for (String dummy : subset) {
                if (conditionMet(dummy)) {
                    validItems.add(dummy);
                } else {
                    loadNext = false;
                    break;
                }
            }
            if (!validItems.isEmpty()) {
                emitter.onNext(validItems);
            }
            if (!loadNext) {
                emitter.onComplete();
            }
        }
    });
}
